class Solution {
    public long largestEvenSum(int[] nums, int k) {
        int n = nums.length;
        Arrays.sort(nums);
        long sum = 0;
        int minOddIn = -1, minEvenIn = -1;
        for (int i = n - 1; i >= n - k; i--) {
            sum += nums[i];
            if (nums[i] % 2 == 1) minOddIn = nums[i];
            else minEvenIn = nums[i];
        }
        if (sum % 2 == 0) return sum;
        int maxOddOut = -1, maxEvenOut = -1;
        for (int i = n - k - 1; i >= 0; i--) {
            if (nums[i] % 2 == 1) { if (maxOddOut < 0) maxOddOut = nums[i]; }
            else if (maxEvenOut < 0) maxEvenOut = nums[i];
        }
        long ans = -1;
        if (minOddIn >= 0 && maxEvenOut >= 0) ans = Math.max(ans, sum - minOddIn + maxEvenOut);
        if (minEvenIn >= 0 && maxOddOut >= 0) ans = Math.max(ans, sum - minEvenIn + maxOddOut);
        return ans;
    }
}
